function getGoldenPath() {
  return [
    { type: 'pageApiCall', method: 'runVerifierStep', args: ["add-cl2-to-nabr"], afterMs: 1500 },
    { type: 'pageApiCall', method: 'runVerifierStep', args: ["add-cl2-to-nai"], afterMs: 1500 },
    { type: 'pageApiCall', method: 'runVerifierStep', args: ["add-br2-to-nai"], afterMs: 1500 },
    { type: 'pageApiCall', method: 'runVerifierStep', args: ["finish-reaction"], afterMs: 300 },
  ];
}

function runVerifierStep(step) {
  const stepType = typeof step === 'string' ? step : step?.type;
  if (stepType === "add-cl2-to-nabr") {
    return beginPour("add-cl2-to-nabr", 'autoplay');
  }
  if (stepType === "add-cl2-to-nai") {
    return beginPour("add-cl2-to-nai", 'autoplay');
  }
  if (stepType === "add-br2-to-nai" || stepType === 'run-autoplay') {
    if (stepType === 'run-autoplay') {
      pourSequence.queueAutoplay(["add-cl2-to-nabr", "add-cl2-to-nai", "add-br2-to-nai"]);
      state.autoplayDelay = 0.18;
      return true;
    }
    return beginPour("add-br2-to-nai", 'autoplay');
  }
  if (stepType === "finish-reaction") {
    return finishReaction();
  }
  return false;
}

installCoursewareTestHarness({
  state,
  mapState() {
    return {
      phase: state.phase,
      activeStep: state.activeStep,
      reactionProgress: state.reactionProgress,
      activePourStep: state.activePour?.stepId || null,
      pendingPourStep: pourSequence.state.pendingStepId || null,
      autoplayMotionActive: isMotionActive() || Boolean(state.activePour),
      completedSteps: { ...state.completedSteps },
      chlorineBottleReturnedHome: dragController.isAtHome('chlorine_bottle'),
      bromineBottleReturnedHome: dragController.isAtHome('bromine_bottle'),
      runtimeInvariants: {
        chlorineBottleReturnedHome: dragController.isAtHome('chlorine_bottle'),
        bromineBottleReturnedHome: dragController.isAtHome('bromine_bottle'),
      },
      recipe: state.recipe,
      source: state.source,
    };
  },
  getVerifierMeta() {
    return {
      supportsGoldenPath: true,
      successPhase: "result",
      failureStatusText: 'Buoc nho thuoc thu chua hoan tat',
    };
  },
  getCapabilities() {
    return recipeCapabilities;
  },
  getStepContract() {
    return recipeStepContract;
  },
  getGoldenPath,
  getDragPath(sampleId = 'chlorine_bottle') {
    if (sampleId === 'bromine_bottle') {
      return {
        type: 'drag',
        from: projectWorldToCanvas(bromineBottle.anchors["nozzle"], camera, renderer),
        to: projectWorldToCanvas(tube3.anchors["pourTarget"], camera, renderer),
        steps: 22,
        afterMs: 500,
      };
    }
    return {
      type: 'drag',
      from: projectWorldToCanvas(chlorineBottle.anchors["nozzle"], camera, renderer),
      to: projectWorldToCanvas(tube1.anchors["pourTarget"], camera, renderer),
      steps: 22,
      afterMs: 500,
    };
  },
  dragFromPageApi({ sampleId } = {}) {
    if (sampleId === 'bromine_bottle') {
      return beginPour("add-br2-to-nai", 'manual');
    }
    return beginPour("add-cl2-to-nabr", 'manual');
  },
  runVerifierStep,
});

autoplayButton?.addEventListener('click', () => {
  if (state.activePour || hasPendingPour() || isMotionActive()) {
    return;
  }
  pourSequence.queueAutoplay(["add-cl2-to-nabr", "add-cl2-to-nai", "add-br2-to-nai"]);
  state.autoplayDelay = 0.18;
});
resetButton?.addEventListener('click', resetScene);

let previousTime = performance.now();
function animate(now = performance.now()) {
  const dt = Math.min(0.05, Math.max(0.001, (now - previousTime) / 1000));
  previousTime = now;
  dragController.update(dt);
  chlorineMotion.update(dt);
  bromineMotion.update(dt);

  if (!hasPendingPour() && !isMotionActive() && !state.activePour && pourSequence.state.queue.length > 0) {
    state.autoplayDelay -= dt;
    if (state.autoplayDelay <= 0) {
      const nextStep = pourSequence.state.queue[0];
      if (!pourSequence.canStartStep(nextStep)) {
        state.autoplayDelay = 0.08;
      } else {
        pourSequence.updateAutoplay();
        state.autoplayDelay = 0.18;
      }
    }
  }

  renderStatus();
  controls.update();
  renderer.render(scene, camera);
  requestAnimationFrame(animate);
}

resetScene();
requestAnimationFrame(animate);

